"""Benchmark the variance of data generated by the simulator.

C1. Monte Carlo variance. Re-run the same experiment with K independent
    seeds and compare the seed-to-seed spread of each metric with the
    standard error a single run reports. A ratio near 1 means the error bars
    in the report are honest. Also: trials needed for a 10% relative
    standard error, and to resolve a decoder difference at 3 sigma.
    (a) stationary nominal point, 50 rounds: NL and matched Bayes;
    (b) nonstationary step in sigma_q: oracle Bayes vs fixed-model Bayes.

C2. Feature variance. How much do sequences differ from each other, as seen
    through the syndromes (the only thing decoders see), within and between
    noise families: per-sequence syndrome spread, lag-1 correlation, excess
    kurtosis, and nearest-lattice flip rate (difficulty). For the LSTM
    drift-training mixture, the share of difficulty variance explained by
    the family label.

Run from the repo root:
    MPLBACKEND=Agg python -m experiments.benchmark_variance
Outputs: results/benchmarks/ (or results/quick/benchmarks/).
"""

import json
import math

import matplotlib

matplotlib.use("Agg")

import matplotlib.pyplot as plt
import numpy as np

from decoders.bayesian.adaptive import OracleBayesDecoder
from decoders.bayesian.grid_filter import BayesGridDecoder, block_size
from experiments.common import (
    BROAD_BOX, NOMINAL, flips_per_trial, get_budget, get_mode, log, make_rng, out_dir,
    run_blocked, torch_device,
)
from simulator import nonstationary as ns
from simulator.noise import L, NoiseModel
from simulator.sim import NearestLattice, Simulator
from simulator.switching import SwitchingNoiseModel, sample_varied
from training.datasets import DRIFT_TRAIN_MIX

OUT = out_dir() / "benchmarks"
OUT.mkdir(parents=True, exist_ok=True)
QUICK = get_mode() == "quick"


# ---------------------------------------------------------------------------
# C1. Monte Carlo variance
# ---------------------------------------------------------------------------
def metrics(rec):
    """Per-replicate metrics and the standard errors one run would report."""
    trials, rounds = rec.shape
    final = rec[:, -1].astype(float)
    per_mean = rec.mean(axis=1)
    per_flip = flips_per_trial(rec) / rounds
    p = final.mean()
    return dict(
        ler_final=p, ler_final_se=math.sqrt(max(p * (1 - p), 1e-300) / trials),
        mean_ler=per_mean.mean(), mean_ler_se=per_mean.std(ddof=1) / math.sqrt(trials),
        flip_rate=per_flip.mean(), flip_rate_se=per_flip.std(ddof=1) / math.sqrt(trials),
        flip_sd_per_trial=per_flip.std(ddof=1),
    )


def replicate_table(reps, keys=("ler_final", "mean_ler", "flip_rate")):
    out = {}
    for k in keys:
        vals = np.array([r[k] for r in reps])
        ses = np.array([r[k + "_se"] for r in reps])
        emp = vals.std(ddof=1)
        out[k] = dict(mean=float(vals.mean()), empirical_sd=float(emp),
                      reported_se=float(ses.mean()),
                      ratio=float(emp / ses.mean()) if ses.mean() > 0 else None,
                      # chi-square interval of the ratio for K replicates
                      ratio_ci95=_ratio_ci(emp / ses.mean(), len(vals)) if ses.mean() > 0
                      else None)
    return out


def _ratio_ci(ratio, k):
    from scipy.stats import chi2
    lo = math.sqrt((k - 1) / chi2.ppf(0.975, k - 1))
    hi = math.sqrt((k - 1) / chi2.ppf(0.025, k - 1))
    return [float(ratio * lo), float(ratio * hi)]


def trials_for_relative_se(rep, key, target=0.10):
    """Trials so that SE / mean = target, from one replicate's per-trial spread."""
    trials = rep["trials"]
    sd = rep[key + "_se"] * math.sqrt(trials)
    mean = rep[key]
    return int(math.ceil((sd / (target * mean)) ** 2)) if mean > 0 else None


def c1_stationary(device):
    K = 10 if QUICK else 30
    N = 1000 if QUICK else 2000
    T = 50
    model = NoiseModel(**NOMINAL)
    budget = get_budget()
    reps = {"NL": [], "Bayes (matched)": []}
    diffs = []
    for k in range(K):
        d, n = model.sample(make_rng("dev", "benchmark_var_c1", k), N, T)
        nl = run_blocked(NearestLattice(), d, n, N)
        dec = BayesGridDecoder(model.sigma_q, model.sigma_m, model.rho, n_x=96, device=device)
        by = run_blocked(dec, d, n, block_size(dec, budget.filter_block_bytes))
        for name, rec in (("NL", nl), ("Bayes (matched)", by)):
            m = metrics(rec)
            m["trials"] = N
            reps[name].append(m)
        dd = (flips_per_trial(nl) - flips_per_trial(by)) / T
        diffs.append(dict(diff=dd.mean(), diff_se=dd.std(ddof=1) / math.sqrt(N),
                          diff_sd=dd.std(ddof=1)))
    out = dict(replicates=K, trials=N, rounds=T, point="nominal (sigma_q=0.2L, "
               "sigma_m=0.05L, rho=0.9)", decoders={})
    for name, rs in reps.items():
        out["decoders"][name] = dict(
            table=replicate_table(rs),
            trials_for_10pct={k: trials_for_relative_se(rs[0], k)
                              for k in ("ler_final", "mean_ler", "flip_rate")},
            raw=[{k: r[k] for k in ("ler_final", "mean_ler", "flip_rate")} for r in rs])
    dv = np.array([d["diff"] for d in diffs])
    se = np.mean([d["diff_se"] for d in diffs])
    out["paired_nl_minus_bayes"] = dict(
        mean=float(dv.mean()), empirical_sd=float(dv.std(ddof=1)), reported_se=float(se),
        ratio=float(dv.std(ddof=1) / se),
        trials_for_3sigma=int(math.ceil((3 * diffs[0]["diff_sd"] / dv.mean()) ** 2)))
    log(f"C1a: {K} replicates x {N} trials done")
    return out


def c1_nonstationary(device):
    K = 6 if QUICK else 12
    N = 300 if QUICK else 600
    T = 150 if QUICK else 400
    sp = ns.spec("step", target="sigma_q", before=0.20 * L, after=0.26 * L)
    budget = get_budget()
    reps = {"Bayes (oracle)": [], "Bayes (nominal)": []}
    diffs = []
    for k in range(K):
        d, n, sch = ns.sample(sp, make_rng("dev", "benchmark_var_c1ns", k), N, T)
        orc = OracleBayesDecoder(device=device)
        ro = run_blocked(orc, d, n, block_size(orc, budget.filter_block_bytes), schedule=sch)
        fx = BayesGridDecoder(NOMINAL["sigma_q"], NOMINAL["sigma_m"], NOMINAL["rho"], n_x=96,
                              device=device)
        rf = run_blocked(fx, d, n, block_size(fx, budget.filter_block_bytes))
        for name, rec in (("Bayes (oracle)", ro), ("Bayes (nominal)", rf)):
            m = metrics(rec)
            m["trials"] = N
            reps[name].append(m)
        dd = (flips_per_trial(rf) - flips_per_trial(ro)) / T
        diffs.append(dict(diff=dd.mean(), diff_se=dd.std(ddof=1) / math.sqrt(N),
                          diff_sd=dd.std(ddof=1)))
        log(f"C1b: replicate {k + 1}/{K}")
    dv = np.array([d["diff"] for d in diffs])
    se = np.mean([d["diff_se"] for d in diffs])
    sd1 = np.mean([d["diff_sd"] for d in diffs])
    out = dict(replicates=K, trials=N, rounds=T, point="step sigma_q 0.20 -> 0.26 L",
               decoders={name: dict(table=replicate_table(rs, ("flip_rate",)),
                                    trials_for_10pct=trials_for_relative_se(rs[0], "flip_rate"))
                         for name, rs in reps.items()})
    out["paired_fixed_minus_oracle"] = dict(
        mean=float(dv.mean()), empirical_sd=float(dv.std(ddof=1)), reported_se=float(se),
        ratio=float(dv.std(ddof=1) / se),
        trials_for_3sigma=int(math.ceil((3 * sd1 / dv.mean()) ** 2)) if dv.mean() > 0 else None,
        # per-trial flip-rate variance scales ~1/T: scale to the E9-E11 sequence length
        trials_for_3sigma_at_ns_rounds=int(math.ceil((3 * sd1 / dv.mean()) ** 2 * T
                                                     / get_budget().ns_rounds))
        if dv.mean() > 0 else None,
        ns_rounds=get_budget().ns_rounds)
    log(f"C1b: {K} replicates x {N} trials x {T} rounds done")
    return out


# ---------------------------------------------------------------------------
# C2. feature variance
# ---------------------------------------------------------------------------
def syndrome_features(d, n):
    """Per-sequence features of the syndrome stream and NL difficulty."""
    trials, rounds = d.shape
    res = Simulator(trials=trials, rounds=rounds).run(NearestLattice(), d, n)
    s = res.syndromes / L
    sc = s - s.mean(axis=1, keepdims=True)
    var = (sc**2).mean(axis=1)
    lag1 = (sc[:, :-1] * sc[:, 1:]).mean(axis=1) / np.maximum(var, 1e-12)
    kurt = (sc**4).mean(axis=1) / np.maximum(var, 1e-12) ** 2 - 3
    flips = flips_per_trial(res.logical_errors) / rounds
    return dict(syn_sd=np.sqrt(var), syn_lag1=lag1, syn_excess_kurtosis=kurt, nl_flip=flips)


def family_samples(N, T_short, T_long):
    rng = lambda k: make_rng("dev", "benchmark_var_c2", k)
    out = {}
    d, n = NoiseModel(**NOMINAL).sample(rng(0), N, T_short)
    out["stationary nominal (E1)"] = (d, n, T_short)
    r = rng(1)
    d, n = sample_varied(r, r.uniform(*BROAD_BOX["rho"], N), r.uniform(*BROAD_BOX["sigma_q"], N),
                         r.uniform(*BROAD_BOX["sigma_m"], N), T_short)
    out["broad box (LSTM-broad training)"] = (d, n, T_short)
    d, n = SwitchingNoiseModel().sample(rng(2), N, T_short)
    out["regime switching (E6)"] = (d, n, T_short)
    from experiments.run_nonstationary import E10_POINTS, E9_POINTS
    for k, (pid, sp, _) in enumerate(E9_POINTS + E10_POINTS):
        d, n, _ = ns.sample(sp, rng(10 + k), N, T_long)
        out[f"{pid} (E9/E10)"] = (d, n, T_long)
    d, n, _, which = ns.sample_mixture(DRIFT_TRAIN_MIX, rng(50), N, T_long)
    out["drift training mix (LSTM-drift)"] = (d, n, T_long, which)
    return out


def c2():
    N = 1000 if QUICK else 4000
    T_short, T_long = 50, get_budget().ns_rounds
    fams = family_samples(N, T_short, T_long)
    table, raw = {}, {}
    for name, item in fams.items():
        d, n, T = item[:3]
        f = syndrome_features(d, n)
        raw[name] = f
        table[name] = dict(rounds=T, **{
            k: dict(p05=float(np.percentile(v, 5)), median=float(np.median(v)),
                    p95=float(np.percentile(v, 95)), sd=float(v.std()))
            for k, v in f.items()})
        if len(item) == 4:
            which = item[3]
            y = f["nl_flip"]
            groups = [y[which == g] for g in np.unique(which)]
            between = sum(len(g) * (g.mean() - y.mean()) ** 2 for g in groups) / len(y)
            table[name]["difficulty_variance_explained_by_family"] = float(between / y.var())
    out = dict(trials=N, table=table)

    keys = ("syn_sd", "syn_lag1", "syn_excess_kurtosis", "nl_flip")
    labels = list(raw)
    fig, axes = plt.subplots(1, len(keys), figsize=(4.2 * len(keys), 0.42 * len(labels) + 1.8),
                             sharey=True)
    for ax, k in zip(axes, keys):
        data = [raw[name][k] for name in labels]
        ax.boxplot(data, orientation="horizontal", whis=(5, 95), showfliers=False, widths=0.6)
        ax.set_title(k, fontsize=10)
        ax.grid(alpha=0.3, axis="x")
        if k == "nl_flip":
            ax.set_xscale("symlog", linthresh=1e-3)
    axes[0].set_yticks(range(1, len(labels) + 1), labels, fontsize=8)
    fig.suptitle("Per-sequence variability of simulated data, seen through the syndromes "
                 "(boxes: quartiles, whiskers: 5-95%)")
    fig.tight_layout()
    fig.savefig(OUT / "variance_features.png", dpi=150)
    plt.close(fig)
    log(f"C2: {len(fams)} families x {N} sequences done")
    return out


def main():
    device = torch_device()
    log(f"benchmark_variance: mode={get_mode()} device={device}")
    out = dict(C1_stationary=c1_stationary(device), C1_nonstationary=c1_nonstationary(device),
               C2=c2())
    (OUT / "benchmark_variance.json").write_text(json.dumps(out, indent=1, default=float))

    # figure: replicate spread vs reported SE (C1a)
    st = out["C1_stationary"]["decoders"]
    fig, axes = plt.subplots(1, 3, figsize=(13, 3.8))
    for ax, k in zip(axes, ("ler_final", "mean_ler", "flip_rate")):
        for j, (name, v) in enumerate(st.items()):
            vals = np.array([r[k] for r in v["raw"]])
            tab = v["table"][k]
            ax.errorbar([j], [tab["mean"]], yerr=[[2 * tab["reported_se"]], [2 * tab["reported_se"]]],
                        fmt="none", ecolor="C3", capsize=8, lw=2, label="±2 reported SE" if j == 0 else None)
            ax.scatter(np.full(len(vals), j) + np.random.default_rng(0).uniform(-0.15, 0.15, len(vals)),
                       vals, s=10, color="C0", alpha=0.7, label="replicates" if j == 0 else None)
        ax.set_xticks(range(len(st)), list(st))
        ax.set_yscale("log")
        ax.set_title(k)
        ax.grid(alpha=0.3, which="both")
    axes[0].legend(fontsize=8)
    fig.suptitle("Seed-to-seed spread vs the standard error a single run reports (nominal point)")
    fig.tight_layout()
    fig.savefig(OUT / "variance_mc.png", dpi=150)
    plt.close(fig)
    log(f"benchmark_variance: wrote {OUT}")


if __name__ == "__main__":
    main()
